WALK_FORWARD_REQUIRED_COLUMNS = {
    "Date origine",
    "Date",
    "Prix projeté LPPL",
    "Prix réel",
    "Sigma résiduel",
    "Phase angulaire",
}


@st.cache_data
def load_embedded_walk_forward():
  """Charge les projections intégrées au fichier principal Cloud."""
  if PRECOMPUTED_WALK_FORWARD_CSV_B64 is None:
    return pd.DataFrame()
  csv_content = base64.b64decode(PRECOMPUTED_WALK_FORWARD_CSV_B64).decode("utf-8")
  data = pd.read_csv(io.StringIO(csv_content))
  if not WALK_FORWARD_REQUIRED_COLUMNS.issubset(data.columns):
    return pd.DataFrame()
  data["Date origine"] = pd.to_datetime(data["Date origine"])
  data["Date"] = pd.to_datetime(data["Date"])
  return data


@st.cache_data
def load_embedded_rolling_walk_forward():
  """Charge l'analyse de stabilité intégrée au fichier principal Cloud."""
  if PRECOMPUTED_ROLLING_WALK_FORWARD_CSV_B64 is None:
    return pd.DataFrame()
  csv_content = base64.b64decode(
      PRECOMPUTED_ROLLING_WALK_FORWARD_CSV_B64
  ).decode("utf-8")
  data = pd.read_csv(io.StringIO(csv_content))
  required_columns = {
      "Date Evaluation",
      "RMSE Out-Of-Sample (%)",
      "MAE Out-Of-Sample (%)",
  }
  if not required_columns.issubset(data.columns):
    return pd.DataFrame()
  data["Date Evaluation"] = pd.to_datetime(data["Date Evaluation"])
  return data
