# Analyse LPPL Lock-In intégrée pour une version Cloud autonome.
# Cumulative calibration of the global LPPL, without future observations.
import numpy as np
import pandas as pd
from scipy.optimize import differential_evolution


def design_matrix(days, omega, decay=None):
    x = np.log(np.asarray(days, dtype=float))
    e1 = e2 = np.ones_like(x)
    if decay is not None:
        t = (2009.0082 + np.exp(x) / 365.25 - 2010.0) / 16.0
        e1 = 0.35 * np.exp(-decay * t) + 0.05
        e2 = (0.15 + 0.12 * np.sin(t * np.pi * 1.5)
              * np.exp(-((t - 0.3) ** 2) / 0.1)
              + 0.08 + 0.12 * (1 - np.exp(-3 * t))
              + 0.06 + 0.02 * np.sin(t * np.pi * 2))
    return np.column_stack([np.ones_like(x), x,
                            e1 * np.cos(omega * x), e1 * np.sin(omega * x),
                            e2 * np.cos(4 * omega * x), e2 * np.sin(4 * omega * x)])


def cumulative_fits(data, targets, omega_bounds=(6.0, 12.0), step_days=90,
                    warmup_years=4, use_energy=False):
    data = data[['Date', 'Days', 'Close']].copy()
    data['Date'] = pd.to_datetime(data['Date'], errors='coerce')
    for col in ['Days', 'Close']:
        data[col] = pd.to_numeric(data[col], errors='coerce')
    data = data.loc[data['Date'].notna() & np.isfinite(data['Days'])
                    & np.isfinite(data['Close']) & (data['Days'] > 0)
                    & (data['Close'] > 0)].sort_values('Date').drop_duplicates('Date')
    if len(data) < 365:
        return pd.DataFrame()
    days = data['Days'].to_numpy(float)
    prices = np.log(data['Close'].to_numpy(float))
    dates = data['Date'].reset_index(drop=True)
    first = dates.iloc[0] + pd.Timedelta(days=int(np.ceil(365.25 * warmup_years)))
    origins = pd.date_range(first, dates.iloc[-1], freq=f'{step_days}D').union(
        pd.DatetimeIndex([dates.iloc[-1]]) if dates.iloc[-1] >= first else pd.DatetimeIndex([]))
    ends = sorted(set(int(dates.searchsorted(d, side='right')) for d in origins))
    rows = []
    for end in ends:
        if end < 365:
            continue
        x, y = days[:end], prices[:end]
        def solve(params):
            matrix = design_matrix(x, params[0], params[1] if use_energy else None)
            coef, _, rank, _ = np.linalg.lstsq(matrix, y, rcond=None)
            mse = float(np.mean((y - matrix @ coef) ** 2))
            return (mse if rank == 6 else np.inf), coef
        bounds = [tuple(omega_bounds)] + ([(0.5, 5.0)] if use_energy else [])
        result = differential_evolution(lambda p: solve(p)[0], bounds,
                                        seed=8081, popsize=12, maxiter=120,
                                        tol=1e-7, polish=True)
        mse, coef = solve(result.x)
        if not np.isfinite(mse):
            continue
        omega = float(result.x[0])
        decay = float(result.x[1]) if use_energy else None
        row = {'Date': dates.iloc[end-1], 'β': coef[1], 'ω': omega,
               'Amplitude macro': np.hypot(coef[2], coef[3]),
               'Amplitude micro': np.hypot(coef[4], coef[5]),
               'Phase macro (°)': np.degrees(np.arctan2(-coef[3], coef[2])),
               'Phase micro (°)': np.degrees(np.arctan2(-coef[5], coef[4])),
               'R²': 1 - mse / np.var(y) if np.var(y) > 0 else np.nan,
               'RMSE log': np.sqrt(mse), 'Convergence': bool(result.success),
               'ω en borne': min(abs(omega - b) for b in omega_bounds) < 0.01,
               'Décroissance énergie': decay, 'Observations': end}
        for target in targets:
            target = pd.Timestamp(target)
            if target <= row['Date']:
                continue
            target_day = days[end-1] + (target - row['Date']).total_seconds() / 86400
            prediction = float((design_matrix([target_day], omega, decay) @ coef)[0])
            row[f'Prix au {target:%Y-%m-%d}'] = np.exp(prediction) if -700 < prediction < 700 else np.nan
        rows.append(row)
    return pd.DataFrame(rows)


def render_lock_in(data, use_energy):
    import streamlit as st
    import plotly.graph_objects as go
    from plotly.subplots import make_subplots

    st.markdown('---')
    st.subheader('🔒 LPPL Lock-In — stabilité des paramètres et des projections')
    st.caption('Recalibrages cumulatifs du LPPL général à ω et 4ω, uniquement avec les '
               'observations disponibles à chaque date. Même âge minimal que le panneau Power Law.')
    st.caption('Modèle actif : ' + ('avec modulation énergétique.' if use_energy else 'classique.'))
    with st.expander('Méthode et limites'):
        st.markdown('La pente, la fréquence, les amplitudes et les phases sont réestimées à chaque '
                    'origine. Avec énergie, la décroissance est aussi réestimée ; les facteurs '
                    'd’échelle sont absorbés dans les amplitudes. Aucun paramètre ajusté aujourd’hui '
                    'n’est réutilisé dans le passé. Les phases utilisent ln(âge en jours) et sont '
                    'circulaires : −180° et +180° sont équivalents. Une amplitude proche de zéro '
                    'rend sa phase peu interprétable. Les prix sont comparés à dates calendaires '
                    'fixes. R² mesure l’ajustement historique, pas la qualité prédictive. '
                    'Une stabilisation cumulative peut aussi venir du poids croissant de l’historique ; '
                    'elle ne garantit pas les prévisions. Les bornes de recherche sont des hypothèses fixes.')
    last_observation = pd.to_datetime(data['Date']).max()
    with st.form('lppl_lock_form'):
        bounds = st.slider('Plage de recherche de ω', 2.0, 20.0, (6.0, 12.0), 0.1)
        warmup = st.slider('Historique minimal avant le premier ajustement (années)', 1, 8, 1)
        step = st.selectbox('Espacement des recalibrages (jours)', [30, 90, 180, 365], index=1)
        run = st.form_submit_button('Calculer le LPPL Lock-In')
    parameter_results = st.container()
    with st.form('lppl_lock_projection_form'):
        target_date = st.date_input(
            'Date cible de la projection (JJ/MM/AAAA)',
            value=(last_observation + pd.DateOffset(years=1)).date(),
            min_value=pd.to_datetime(data['Date']).min().date(),
            max_value=pd.Timestamp('2200-12-31').date(),
            format='DD/MM/YYYY', key='lppl_lock_target_date',
            help='Saisissez le jour, le mois et l’année, puis actualisez la projection. '
                 'Une date passée permet de revoir les projections faites avant cette date.')
        update_projection = st.form_submit_button('Actualiser la projection')
    # The result key includes observations and settings, so stale results are never displayed.
    signature = (int(pd.util.hash_pandas_object(data, index=True).sum()), use_energy,
                 tuple(bounds), warmup, step, target_date)
    if run or update_projection:
        if bounds[0] >= bounds[1]:
            st.warning('Choisissez deux bornes de fréquence distinctes.')
            return
        if target_date is None:
            st.warning('Choisissez une date cible.')
            return
        targets = [pd.Timestamp(target_date)]
        cached = st.cache_data(max_entries=4, show_spinner=False)(cumulative_fits)
        with st.spinner('Recalibrages historiques du LPPL général…'):
            result = cached(data, targets, bounds, step, warmup, use_energy)
        st.session_state['lppl_lock_result'] = (signature, result)
    saved = st.session_state.get('lppl_lock_result')
    if saved is None or saved[0] != signature:
        st.info('Lancez le calcul pour les données et réglages sélectionnés.')
        return
    result = saved[1]
    if result.empty:
        st.warning('Historique insuffisant pour la durée minimale choisie.')
        return
    with parameter_results:
        last = result.iloc[-1]
        cols = st.columns(3)
        for col, name in zip(cols, ['β', 'ω', 'R²']):
            col.metric(f'{name} final', f'{last[name]:.4f}')
        if (~result['Convergence']).any() or result['ω en borne'].any():
            st.warning(f"{int((~result['Convergence']).sum())} ajustement(s) sans convergence confirmée ; "
                       f"{int(result['ω en borne'].sum())} fréquence(s) proche(s) des bornes. "
                       'Ces points nécessitent une lecture prudente ou une plage de recherche élargie.')
        fig = make_subplots(rows=2, cols=2, subplot_titles=['Pente β', 'Fréquence ω',
                                                           'Amplitudes (log-prix)', 'Phases circulaires (°)'])
        for names, row, col in [(['β'], 1, 1), (['ω'], 1, 2),
                               (['Amplitude macro', 'Amplitude micro'], 2, 1),
                               (['Phase macro (°)', 'Phase micro (°)'], 2, 2)]:
            for name in names:
                fig.add_trace(go.Scatter(x=result['Date'], y=result[name], name=name,
                                         mode='markers' if row == 2 and col == 2 else 'lines+markers'), row=row, col=col)
        fig.update_layout(template='plotly_dark', height=650, margin=dict(t=45, b=30))
        st.plotly_chart(fig, width='stretch')
    forecasts = [c for c in result if c.startswith('Prix au ')]
    projection_rows = result.loc[result['Date'] < pd.Timestamp(target_date)]
    if forecasts:
        projection_rows = projection_rows.dropna(subset=forecasts, how='all')
    if not forecasts or projection_rows.empty:
        st.info('Aucune projection disponible avant cette date cible. Choisissez une date plus '
                'tardive ou réduisez l’historique minimal avant le premier ajustement.')
    else:
        st.caption('Seuls les recalibrages antérieurs à la date cible sont affichés : '
                   'chaque projection utilise uniquement les observations disponibles à son origine.')
        projection = go.Figure()
        for name in forecasts:
            projection.add_trace(go.Scatter(x=projection_rows['Date'], y=projection_rows[name],
                                            name=name, mode='lines+markers'))
        projection.update_layout(template='plotly_dark', height=420,
                                 title=f'Révisions de la projection au {target_date:%d/%m/%Y}',
                                 xaxis_title='Date du recalibrage', yaxis_title='Prix projeté ($)',
                                 yaxis_type='log')
        st.plotly_chart(projection, width='stretch')
        if len(projection_rows) > 1:
            revision = projection_rows[forecasts].iloc[-1] / projection_rows[forecasts].iloc[-2] - 1
            st.caption('Dernière révision des projections avant la date cible : ' + ' · '.join(
                f'{name[8:]} : {value:+.1%}' for name, value in revision.items()))
    with st.expander('Résultats des recalibrages'):
        st.dataframe(result, width='stretch', hide_index=True)
