with tab_stabilite_lppl:
  st.header("Stabilité LPPL")

  # ============================================================================
  # POWER LAW LOCK-IN — PENTE OLS CUMULATIVE
  # ============================================================================
  st.markdown("---")
  st.subheader("🔒 Power Law Lock-In — pente OLS cumulative")
  st.caption(
      "La pente β est recalculée à chaque date avec toutes les observations "
      "antérieures disponibles. Une stabilisation progressive indique que la "
      "pente devient moins sensible aux nouveaux cycles."
  )
  with st.expander("❓ Lecture et limites", expanded=False):
    st.markdown(
        "À chaque date, une régression OLS de $\\log(P)$ sur $\\log(âge)$ est "
        "estimée depuis le début de la série. La courbe affiche la pente β et "
        "le R² final est celui de la régression cumulative actuelle. Ce test "
        "décrit une stabilité historique ; il ne garantit ni une loi permanente "
        "ni une trajectoire future."
    )

  lock_in_min_age = st.slider(
      "Âge minimal pour le calcul cumulatif (années)",
      min_value=1.0,
      max_value=5.0,
      value=1.0,
      step=0.25,
      key="lock_in_min_age",
  )
  lock_in_prices = pd.to_numeric(df["Close"], errors="coerce").to_numpy(dtype=float)
  lock_in_days = pd.to_numeric(df["Days"], errors="coerce").to_numpy(dtype=float)
  lock_in_valid_data = (
      np.isfinite(lock_in_prices) & (lock_in_prices > 0)
      & np.isfinite(lock_in_days) & (lock_in_days > 0)
  )
  lock_in_mask = lock_in_valid_data & (
      pd.to_numeric(df["Days"], errors="coerce").to_numpy(dtype=float) / 365.25
      >= lock_in_min_age
  )
  lock_in_age = (
      pd.to_numeric(df.loc[lock_in_mask, "Days"], errors="coerce").to_numpy(dtype=float)
      / 365.25
  )
  lock_in_price = pd.to_numeric(df.loc[lock_in_mask, "Close"], errors="coerce").to_numpy(dtype=float)
  lock_in_date = df.loc[lock_in_mask, "Date"].reset_index(drop=True)
  lock_in_valid = np.isfinite(lock_in_age) & (lock_in_age > 0) & np.isfinite(lock_in_price) & (lock_in_price > 0)
  lock_in_age = lock_in_age[lock_in_valid]
  lock_in_price = lock_in_price[lock_in_valid]
  lock_in_date = lock_in_date.loc[lock_in_valid].reset_index(drop=True)

  if len(lock_in_age) < 30:
    st.warning("Données insuffisantes après l'âge minimal sélectionné.")
  else:
    lock_in_x = np.log10(lock_in_age)
    lock_in_y = np.log10(lock_in_price)
    lock_in_count = np.arange(1, len(lock_in_x) + 1, dtype=float)
    sum_x = np.cumsum(lock_in_x)
    sum_y = np.cumsum(lock_in_y)
    sum_xx = np.cumsum(lock_in_x ** 2)
    sum_yy = np.cumsum(lock_in_y ** 2)
    sum_xy = np.cumsum(lock_in_x * lock_in_y)
    lock_in_denominator = lock_in_count * sum_xx - sum_x ** 2
    lock_in_beta = np.divide(
        lock_in_count * sum_xy - sum_x * sum_y,
        lock_in_denominator,
        out=np.full_like(lock_in_denominator, np.nan),
        where=np.abs(lock_in_denominator) > 1e-12,
    )
    lock_in_r_squared = np.divide(
        (lock_in_count * sum_xy - sum_x * sum_y) ** 2,
        lock_in_denominator * (lock_in_count * sum_yy - sum_y ** 2),
        out=np.full_like(lock_in_denominator, np.nan),
        where=(np.abs(lock_in_denominator) > 1e-12)
        & (np.abs(lock_in_count * sum_yy - sum_y ** 2) > 1e-12),
    )
    lock_in_visible = lock_in_count >= 30
    final_lock_in_beta = float(lock_in_beta[lock_in_visible][-1])
    final_lock_in_r_squared = float(lock_in_r_squared[lock_in_visible][-1])
    recent_lock_in_beta = float(lock_in_beta[lock_in_visible][-min(365, lock_in_visible.sum()):].mean())

    lock_metric_1, lock_metric_2, lock_metric_3 = st.columns(3)
    lock_metric_1.metric("β final", f"{final_lock_in_beta:.4f}", border=True)
    lock_metric_2.metric("R² final", f"{final_lock_in_r_squared:.4f}", border=True)
    lock_metric_3.metric(
        "β moyen récent (≤ 365 j)", f"{recent_lock_in_beta:.4f}", border=True
    )

    fig_lock_in = go.Figure()
    fig_lock_in.add_trace(go.Scatter(
        x=lock_in_age[lock_in_visible], y=lock_in_beta[lock_in_visible],
        mode="lines", name="β OLS cumulatif",
        line=dict(color="#38BDF8", width=2.3),
        customdata=list(zip(
            lock_in_date.loc[lock_in_visible].dt.strftime("%d/%m/%Y"),
            lock_in_r_squared[lock_in_visible],
        )),
        hovertemplate="Date : %{customdata[0]}<br>Âge : %{x:.2f} ans<br>β cumulatif : %{y:.4f}<br>R² cumulatif : %{customdata[1]:.4f}<extra></extra>",
    ))
    fig_lock_in.add_hline(
        y=final_lock_in_beta, line_dash="dash", line_color="#FACC15",
        annotation_text=f"β final : {final_lock_in_beta:.4f}",
        annotation_position="bottom right", annotation_font_color="#FACC15",
    )
    fig_lock_in.add_vline(
        x=(pd.Timestamp("2016-01-01") - GENESIS_DATE).days / 365.25,
        line_dash="dot", line_color="rgba(255,255,255,0.45)",
        annotation_text="2016", annotation_position="bottom right",
    )
    fig_lock_in.update_layout(
        template="plotly_dark", height=440,
        title="Pente OLS cumulative — log(prix) ~ log(âge)",
        xaxis_title="Âge de Bitcoin (années)", yaxis_title="Pente β",
        margin=dict(l=20, r=20, t=45, b=25),
        legend=dict(orientation="h", y=1.12, x=0.5, xanchor="center"),
    )
    st.plotly_chart(fig_lock_in, width="stretch")

  # ============================================================================
  # LPPL GENERAL LOCK-IN
  # ============================================================================
  render_lock_in(df.loc[lock_in_mask, ["Date", "Days", "Close"]], use_energy)


